{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Sound Bath Gatherings</title>
  <meta name="description" content="A sensory series of sound baths in {{CITY}}, {{STATE}}. Calm, alignment, embodiment.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Primary">
        <a href="/">Gather</a>
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Intimate</a>
        <a href="/pricing.html">Offerings</a>
        <a href="/about.html">Story</a>
        <a href="/faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button id="menuToggle" class="menu-toggle" aria-expanded="false">☰</button>
    </div>
  </header>

  <main>
    <!-- hero -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg');">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">A stillness that sings</h1>
          <p class="lead">{{TAGLINE}}</p>
          <div class="hero-cta">
            <a class="btn primary" href="/events.html">Next gathering — {{NEXT_EVENT_DATE}}</a>
            <a class="btn ghost" href="/about.html">Meet {{FACILITATOR_NAME}}</a>
          </div>
        </div>
        <aside class="hero-meta">
          <dl>
            <dt>Where</dt>
            <dd>{{VENUE_NAME}}, {{CITY}}</dd>
            <dt>Reserve</dt>
            <dd><a href="/book.html">Book a spot</a></dd>
            <dt>Call</dt>
            <dd><a href="tel:{{PHONE}}">{{PHONE}}</a></dd>
          </dl>
        </aside>
      </div>
    </section>

    <!-- myth_vs_truth -->
    <section id="myths" class="section soft">
      <div class="wrap">
        <h2 class="section-title">Myths & Gentle Truths</h2>
        <div class="grid-2">
          <article>
            <h3>Myth</h3>
            <p>Sound baths are merely background noise for meditation.</p>
          </article>
          <article>
            <h3>Truth</h3>
            <p>They are a crafted journey of vibration: breath, resonance, tonality — a map for felt release.</p>
          </article>
          <article>
            <h3>Myth</h3>
            <p>You must be an expert to receive benefit.</p>
          </article>
          <article>
            <h3>Truth</h3>
            <p>Ease is the invitation. Bring curiosity and your body does the rest.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- pillars -->
    <section id="pillars" class="section earth">
      <div class="wrap">
        <h2 class="section-title">Three Pillars of the Series</h2>
        <div class="pillars">
          <div class="pillar">
            <h4>Sense</h4>
            <p>Intentional acoustics: crystal bowls, monochord and chimes unfold a soft architecture of sound.</p>
          </div>
          <div class="pillar">
            <h4>Rest</h4>
            <p>Slow transitions, guided breath and silence to integrate the waves between tones.</p>
          </div>
          <div class="pillar">
            <h4>Return</h4>
            <p>Light reintegration: journaling prompts, gentle tea and time to ground after the session.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- case_notes -->
    <section id="case-notes" class="section soft">
      <div class="wrap">
        <h2 class="section-title">Notes from the room</h2>
        <ul class="notes">
          <li class="note"><strong>"The gong opened a doorway."</strong> — a regular on evening circles.</li>
          <li class="note"><strong>"I slept like a cave."</strong> — an executive after a midweek session.</li>
          <li class="note"><strong>"My back unwound with the monochord."</strong> — a 1:1 participant.</li>
        </ul>
        <p class="small">Each gathering is a discreet composition — instruments change, intentions remain steady.</p>
      </div>
    </section>

    <!-- faq -->
    <section id="faq" class="section earth">
      <div class="wrap">
        <h2 class="section-title">Practical Questions</h2>
        <div class="faq-grid">
          <div class="q">
            <h4>What to bring?</h4>
            <p>Yoga mat or blanket, a pillow for your head, water, and an open layer. We provide bolsters and blankets if needed.</p>
          </div>
          <div class="q">
            <h4>Contraindications</h4>
            <p>If you are pregnant, have uncontrolled epilepsy, recent head injury, or serious cardiac conditions, please consult your physician and inform the facilitator before attending.</p>
          </div>
          <div class="q">
            <h4>Session Flow</h4>
            <p>Arrival & settling (10m) — Guided breath & intention (10m) — Sound journey (40–50m) — Silent integration & return (10–15m) — Tea and soft close.</p>
          </div>
          <div class="q">
            <h4>Instruments you might hear</h4>
            <p>Crystal singing bowls, koshi chimes, tuning forks and a suspended gong — textures that shape different edges of silence.</p>
          </div>
        </div>
        <p class="muted">If you have specific medical concerns, contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> before booking.</p>
      </div>
    </section>

    <!-- cta -->
    <section class="section cta-band">
      <div class="wrap cta-wrap">
        <h3>Reserve your place for the next sound bath</h3>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/private-sessions.html">Private · 1:1 · Couples</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-left">
        <p>&copy; {{BUSINESS_NAME}} · {{CITY}}, {{STATE}}</p>
      </div>
      <div class="foot-right">
        <a href="/contact.html">Contact</a>
        <a href="/faq.html">FAQ</a>
        <a href="/pricing.html">Pricing</a>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
