{"path":"assets/css/styles.css","content":"/* earthy_warm — minimal_poetic */
:root{
  --bg:#f7efe6;
  --muted:#7a6b58;
  --accent:#8b5e34;
  --accent-2:#c78b5a;
  --deep:#3e2f24;
  --glass: rgba(255,255,255,0.6);
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body.earthy{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.6;color:var(--deep);background:linear-gradient(180deg,var(--bg),#efe6db);}
.wrap{max-width:var(--max-width);margin:0 auto;padding:2rem}
.site-header{background:linear-gradient(90deg,rgba(139,94,52,.06),transparent);backdrop-filter: blur(4px);position:sticky;top:0;z-index:10;border-bottom:1px solid rgba(62,47,36,.04)}
.site-header .wrap{display:flex;align-items:center;gap:1rem;justify-content:space-between;padding:1rem 2rem}
.brand{font-weight:600;color:var(--deep);text-decoration:none}
.nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
.nav a.cta{background:var(--accent);color:white;padding:.5rem .8rem;border-radius:6px}
.menu-toggle{display:none;background:none;border:none;font-size:1.2rem}
.hero{padding:3rem 0;background-size:cover;background-repeat:no-repeat}
.hero-inner{display:flex;gap:2rem;align-items:center}
.hero-copy{flex:1}
.title{font-size:clamp(1.6rem,3vw,2.6rem);margin:0;color:var(--deep);font-weight:700}
.lead{margin:.6rem 0;color:var(--muted)}
.hero-cta .btn{display:inline-block;margin-right:.6rem;margin-top:1rem}
.btn{padding:.6rem 1rem;border-radius:8px;text-decoration:none;border:1px solid rgba(62,47,36,.06);font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.btn.ghost{background:var(--glass);color:var(--deep)}
.hero-meta{width:220px;border-left:1px dashed rgba(62,47,36,.06);padding-left:1rem}
.section{padding:3rem 0}
.section.soft{background:rgba(255,255,255,0.6)}
.section.earth{background:linear-gradient(180deg,rgba(199,139,90,.06),transparent)}
.section-title{font-size:1.1rem;margin-bottom:1rem;color:var(--accent)}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.pillars{display:flex;gap:1rem}
.pillar{background:white;padding:1rem;border-radius:10px;box-shadow:0 6px 18px rgba(62,47,36,.05)}
.notes{list-style:none;padding:0;margin:1rem 0}
.note{background:linear-gradient(90deg,#fff,rgba(255,255,255,.9));padding:1rem;border-radius:8px;margin-bottom:.6rem}
.faq-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}
.muted{color:var(--muted);font-size:.9rem}
.cta-band{background:linear-gradient(90deg,rgba(139,94,52,.08),rgba(199,139,90,.04));padding:2rem 0}
.cta-wrap{display:flex;align-items:center;justify-content:space-between;gap:1rem}
.site-footer{border-top:1px solid rgba(62,47,36,.04);padding:1rem 0;margin-top:2rem}
.foot-right a{margin-left:1rem;color:var(--muted);text-decoration:none}
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .hero-meta{width:100%;border-left:none;padding-left:0;border-top:1px dashed rgba(62,47,36,.04);padding-top:1rem;margin-top:1rem}
  .nav{display:none}
  .menu-toggle{display:inline-block}
}
/* subtle pattern overlay using SVG file */
body::before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.12;background-image:url('../img/pattern.svg');background-repeat:repeat;background-size:220px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Menu toggle for small screens
  var btn = document.getElementById('menuToggle');
  var nav = document.querySelector('.nav');
  btn && btn.addEventListener('click', function(){
    var expanded = this.getAttribute('aria-expanded') === 'true';
    this.setAttribute('aria-expanded', String(!expanded));
    nav.style.display = expanded ? 'none' : 'flex';
  });

  // Smooth internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault();
      var t = document.querySelector(this.getAttribute('href'));
      t && t.scrollIntoView({behavior:'smooth'});
    });
  });

  // Insert next event date from placeholder into elements that contain it
  document.querySelectorAll('*').forEach(function(el){
    if(el.innerHTML && el.innerHTML.indexOf('{{NEXT_EVENT_DATE}}')!==-1){
      el.innerHTML = el.innerHTML.replace(/\{\{NEXT_EVENT_DATE\}\}/g, '{{NEXT_EVENT_DATE}}');
    }
  });

  // Lightweight reveal on scroll
  var observer = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add('in'); }
    });
  },{threshold:.08});
  document.querySelectorAll('.section').forEach(function(s){ observer.observe(s); });
})();
"} 
